## Code Example
```javascript
// Minimal EDF scheduler (Node.js)
class Task {
  constructor(id, deadline, payload){ this.id=id; this.deadline=deadline; this.payload=payload; this.cancelled=false; }
}
class EDFScheduler {
  constructor(concurrency=2){ this.queue=[]; this.concurrency=concurrency; this.active=0; this.running=true; }
  enqueue(t){ this.queue.push(t); this.queue.sort((a,b)=>a.deadline-b.deadline); }
  async nextTask(){ while(this.running){ if(this.queue.length){ const t=this.queue.shift(); if(!t.cancelled) return t; continue; } await new Promise(r=>setTimeout(r,1)); } return null; }
  async startWorker(){ if(this.active>=this.concurrency) return; this.active++; (async ()=>{ while(this.running){ const t=await this.nextTask(); if(!t) break; await new Promise(r=>setTimeout(r,10)); console.log(`done ${t.id}`); } this.active--; })(); }
  shutdown(){ this.running=false; }
}
(async ()=>{ const s=new EDFScheduler(2); const now=Date.now(); s.enqueue(new Task(1, now+200, {})); s.enqueue(new Task(2, now+100, {})); s.enqueue(new Task(3, now+150, {})); s.startWorker(); s.startWorker(); setTimeout(()=>s.shutdown(),500);})();
```

## Why This Is Asked

Tests ability to design a scalable, backpressured worker pool for real-time workloads, with fairness, fault tolerance, and clean shutdown—exactly the kind of pattern seen in large chat platforms.

## Key Concepts

- Bounded queue with backpressure
- Dynamic worker scaling (min/max bounds)
- Fairness across users (distribution by UserID)
- Graceful shutdown and worker timeout handling

## Code Example

```go
package main

import (
  "context"
  "fmt"
  "hash/fnv"
  "sync"
  "time"
)

type Task struct {
  UserID  string
  Payload string
}

func worker(ctx context.Context, id int, tasks <-chan Task, wg *sync.WaitGroup) {
  defer wg.Done()
  for {
    select {
    case t := <-tasks:
      // simulate processing
      _ = t
      time.Sleep(5 * time.Millisecond)
      fmt.Printf("worker %d processed %s\n", id, t.Payload)
    case <-ctx.Done():
      return
    }
  }
}

func main() {
  minW, maxW := 2, 6
  queueCap := 64
  queue := make(chan Task, queueCap)
  var wg sync.WaitGroup
  var cancels []context.CancelFunc

  // start min workers
  for i := 0; i < minW; i++ {
    ctx, cancel := context.WithCancel(context.Background())
    cancels = append(cancels, cancel)
    wg.Add(1)
    go worker(ctx, i, queue, &wg)
  }

  // scaler
  go func() {
    ticker := time.NewTicker(100 * time.Millisecond)
    defer ticker.Stop()
    for range ticker.C {
      l := len(queue)
      if l > 32 && len(cancels) < maxW {
        // scale up
        ctx, cancel := context.WithCancel(context.Background())
        cancels = append(cancels, cancel)
        w := len(cancels) - 1
        wg.Add(1)
        go worker(ctx, w, queue, &wg)
      } else if l < 8 && len(cancels) > minW {
        // scale down
        cancel := cancels[len(cancels)-1]
        cancels = cancels[:len(cancels)-1]
        cancel()
      }
    }
  }()

  // producer: enqueue tasks
  for i := 0; i < 1000; i++ {
    t := Task{UserID: fmt.Sprintf("user-%d", i%20), Payload: fmt.Sprintf("payload-%d", i)}
    queue <- t // blocks when full (backpressure)
  }

  // graceful shutdown
  time.Sleep(1 * time.Second)
  for _, c := range cancels {
    c()
  }
  close(queue)
  wg.Wait()
}
```

